"""Pack the dashboards into the ConfigMap Grafana loads them from.

    python3 deploy/cluster/observability/render_dashboards.py

The JSON files in dashboards/ are the source (the format Grafana exports and imports); the
ConfigMap in manifests/ is generated from them, and tests/test_helm.py fails if it is stale.
Standard library only.
"""

import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
TARGET = HERE / "manifests" / "grafana-dashboards.yaml"


def render() -> str:
    lines = [
        "# Generated by render_dashboards.py from dashboards/*.json. Do not edit by hand.",
        "apiVersion: v1",
        "kind: ConfigMap",
        "metadata:",
        "  name: grafana-dashboards",
        "  namespace: observability",
        "data:",
    ]
    for path in sorted((HERE / "dashboards").glob("*.json")):
        compact = json.dumps(json.loads(path.read_text()), ensure_ascii=False, sort_keys=True)
        # JSON is valid YAML; quoted as one scalar so nothing in it is reinterpreted.
        lines.append(f"  {path.name}: {json.dumps(compact, ensure_ascii=False)}")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    TARGET.write_text(render())
    print(f"wrote {TARGET.relative_to(HERE.parents[2])}")
